select

from corgi_activity_comment c
left join corgi_comment_like l on l.comment_id = c.comment_id and l.status = '1'
where c.activity_id = #{activityId}

    and id < #{id}

group by c.comment_id
order by c.id desc
limit #{size}

select
from corgi_activity_comment c left join corgi_comment_like l on l.comment_id = c.comment_id and l.status = '1' where c.activity_id = #{activityId}
and c.id < #{commentId}
group by c.comment_id order by c.id desc

select

from corgi_activity_comment c
where c.comment_id = #{commentId}

select

from corgi_activity_comment c
where comment_user_id = #{comment.comment_user_id}
and ctime < #{comment.ctime}
and user_id != #{comment.comment_user_id}
and not exists(select 1 from corgi_activity_comment c2
where c2.comment_user_id = c.comment_user_id
and c2.activity_id = c.activity_id
and c2.id > c.id)
order by id desc
limit #{size}

select count(1)
from corgi_activity_comment
where activity_id = #{activityId}

select count(1)
from corgi_comment_like
where user_id = #{userId}
  and comment_id = #{commentId}

mapper.update:
update corgi_comment_like
set `status` = #{status}
where user_id = #{userId}
  and comment_id = #{commentId}
